#!/usr/bin/env python3
"""Doré Design 1.0 visual canvas: same workspace/API, real New Westside presentation."""
import os
from pathlib import Path
from http.server import ThreadingHTTPServer
import app_workspace as base
ROOT=Path(__file__).resolve().parent.parent
HTML=r'''<!doctype html><html><head><meta charset="utf-8"><title>Doré Design · New Westside</title><style>
*{box-sizing:border-box}html,body{margin:0;height:100%;font-family:system-ui;background:#bdbdb9;color:#222}#top{height:52px;background:#171717;color:#eee;display:flex;align-items:center;gap:8px;padding:0 14px}button{border:1px solid #666;background:#303030;color:#fff;padding:7px 10px;cursor:pointer}.app{height:calc(100% - 52px);display:grid;grid-template-columns:245px 1fr 285px}.side{background:#f2f1ed;overflow:auto;padding:13px;border-right:1px solid #aaa}.right{border-right:0;border-left:1px solid #aaa}.p{background:#fff;border:1px solid #bbb;padding:9px;margin:6px 0;cursor:pointer}.p.on{border:2px solid #222}.layer{padding:6px 3px;border-bottom:1px solid #ddd;font-size:12px}.stagewrap{overflow:auto;padding:30px}.stage{position:relative;margin:auto;box-shadow:0 10px 36px #0004;overflow:hidden;background:#f7f4ec}.stage:before{content:"";position:absolute;inset:0;pointer-events:none;opacity:.16;background:repeating-linear-gradient(0deg,transparent 0 3px,rgba(20,20,20,.035) 3px 4px)}.node{position:absolute;white-space:pre-line;font-family:"Cormorant Garamond","Noto Serif TC",Georgia,serif;line-height:1.03;cursor:move}.node.sel{outline:2px solid #777;outline-offset:3px}.rule{background:#a2872a}.block{border:1px solid rgba(37,37,37,.38);padding:18px;background:rgba(250,249,245,.72);overflow:hidden;display:flex;flex-direction:column;justify-content:flex-end}.block:before{content:"";position:absolute;left:0;top:0;width:24%;height:3px;background:#a2872a}.block .eye{font-size:11px;letter-spacing:.12em;color:#a2872a;text-transform:uppercase;margin-bottom:auto}.block h2{font-weight:400;font-size:38px;line-height:.94;margin:16px 0 8px}.block p{font:13px/1.45 "Noto Serif TC",Georgia,serif;margin:0}.masthead{position:absolute;left:64px;top:35px;width:1072px;height:72px;object-fit:contain;border-bottom:1px solid rgba(37,37,37,.3);padding-bottom:12px}.home .brand,.home .brand-zh,.home .h-rule{display:none}.home .watch-kicker{top:125px!important;color:#a2872a;letter-spacing:.12em}.home .home-title{top:160px!important;color:#102a43;font-size:68px!important}.home .home-deck{top:330px!important}.home .journal-tower{left:690px!important;top:145px!important;width:390px!important;height:620px!important;background:#102a43;color:#f7f4ec;border:0}.home .journal-tower:after{content:"";position:absolute;right:-10%;top:7%;width:55%;height:72%;border:1px solid rgba(210,188,105,.7);transform:rotate(4deg);background:repeating-radial-gradient(ellipse at 60% 25%,transparent 0 7px,rgba(210,188,105,.18) 8px 9px,transparent 10px 14px),repeating-linear-gradient(118deg,transparent 0 8px,rgba(250,249,245,.10) 9px 10px)}.home .journal-tower h2{font-size:54px;position:relative;z-index:1}.home .journal-tower .eye,.home .journal-tower p{position:relative;z-index:1;color:#d2bc69}.home .wall-horizon{display:none}.home .brick-01{left:64px!important;top:470px!important;width:270px!important;height:260px!important}.home .brick-02{left:342px!important;top:430px!important;width:310px!important;height:300px!important}.home .brick-03{left:64px!important;top:738px!important;width:350px!important;height:190px!important;background:#ece6d8}.home .brick-04{left:422px!important;top:775px!important;width:230px!important;height:153px!important;background:#102a43;color:#f7f4ec}.home .brick-04 h2{font-size:31px}.home .gate-mark{left:785px!important;top:815px!important;color:#a2872a;letter-spacing:.16em}.home .gate-left{left:700px!important;top:870px!important;width:150px!important}.home .gate-right{left:930px!important;top:870px!important;width:150px!important}.home .footer{left:740px!important;top:930px!important;color:#a2872a}.gatearch{position:absolute;left:850px;top:820px;width:80px;height:112px;border:1px solid #a2872a;border-bottom:0;border-radius:50px 50px 0 0;background:linear-gradient(rgba(210,188,105,.05),rgba(162,135,42,.17))}.crenel{position:absolute;left:50px;right:50px;bottom:35px;height:22px;background:linear-gradient(90deg,#102a43 0 8%,transparent 8% 11%,#102a43 11% 24%,transparent 24% 29%,#102a43 29% 42%,transparent 42% 46%,#102a43 46% 63%,transparent 63% 68%,#102a43 68% 79%,transparent 79% 84%,#102a43 84% 100%);opacity:.16}h3{font-size:11px;letter-spacing:.15em;text-transform:uppercase}input,textarea{width:100%;padding:6px;margin:4px 0}textarea{height:120px}.small{font-size:11px;color:#666}</style></head><body><div id="top"><b>DORÉ DESIGN 1.0 · NEW WESTSIDE</b><span id="status">Living Wall</span><button onclick="undo()">Undo</button><button onclick="verifyNow()">Verify</button><button onclick="location.reload()">Refresh</button></div><div class="app"><aside class="side"><h3>Pages</h3><div id="pages"></div><h3>Layers</h3><div id="layers"></div></aside><main class="stagewrap"><div id="stage" class="stage"></div></main><aside class="side right"><h3>Inspector</h3><div id="ins" class="small">Select a layer</div><h3>Visual Grammar</h3><p class="small">黑膠牆 → Editorial Gravity → 5:8 → 華容道 → 城牆垛 → 磚・垛・流</p><p class="small">Doré engraving = trace / presence / image, not wallpaper.</p></aside></div><script>
let w,active='homepage',selected=null,drag=null;async function api(path,opt){let r=await fetch(path,opt?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(opt)}:{});let j=await r.json();if(!r.ok)throw Error(JSON.stringify(j));return j}function pg(){return w.pages.find(p=>p.id===active)||w.pages[0]}function esc(s){return String(s||'').replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]))}function render(){let p=pg();active=p.id;let P=document.getElementById('pages');P.innerHTML='';w.pages.forEach(x=>{let e=document.createElement('div');e.className='p '+(x.id===active?'on':'');e.innerHTML='<b>'+esc(x.name)+'</b><br><span class="small">'+x.nodes.length+' layers</span>';e.onclick=()=>{active=x.id;selected=null;render()};P.appendChild(e)});let L=document.getElementById('layers');L.innerHTML='';p.nodes.forEach(n=>{let e=document.createElement('div');e.className='layer';e.textContent=n.id+' · '+n.type;e.onclick=()=>{selected=n.id;render()};L.appendChild(e)});let s=document.getElementById('stage');s.className='stage '+(p.id==='homepage'?'home':'');s.style.width=p.canvas.w+'px';s.style.height=p.canvas.h+'px';s.innerHTML=p.id==='homepage'?'<img class="masthead" src="/asset/masthead.svg"><div class="gatearch"></div><div class="crenel"></div>':'';p.nodes.forEach(n=>{let e=document.createElement('div');e.className='node '+n.type+' '+n.id+(selected===n.id?' sel':'');e.style.left=n.x+'px';e.style.top=n.y+'px';e.style.width=n.w+'px';if(n.h)e.style.height=n.h+'px';if(n.type==='rule'){}else if(n.type==='block'){e.innerHTML='<div class="eye">'+esc(n.eyebrow)+'</div><h2>'+esc(n.title)+'</h2><p>'+esc(n.body)+'</p>'}else{e.style.fontSize=(n.size||18)+'px';e.style.color=n.role==='hero'?'#102a43':'#252525';e.textContent=n.text||''}e.onpointerdown=ev=>start(ev,e,n);e.onclick=ev=>{ev.stopPropagation();selected=n.id;renderInspector(n)};s.appendChild(e)});document.getElementById('status').textContent=p.name+' · r'+w.revision;if(selected){let n=p.nodes.find(n=>n.id===selected);if(n)renderInspector(n)}}function renderInspector(n){selected=n.id;document.getElementById('ins').innerHTML='<b>'+esc(n.id)+'</b><label>X<input id="ix" value="'+n.x+'"></label><label>Y<input id="iy" value="'+n.y+'"></label><label>W<input id="iw" value="'+n.w+'"></label>'+(n.type==='text'?'<label>Text<textarea id="it">'+esc(n.text)+'</textarea></label>':'')+'<button onclick="saveIns()">Save</button>'}async function saveIns(){let n=pg().nodes.find(n=>n.id===selected),patch={x:+ix.value,y:+iy.value,w:+iw.value};if(n.type==='text')patch.text=it.value;w=await api('/api/workspace',{op:'set_node',page_id:active,id:selected,patch});render()}function start(ev,e,n){if(ev.button!==0)return;ev.preventDefault();drag={e,id:n.id,sx:ev.clientX,sy:ev.clientY,x:n.x,y:n.y,nx:n.x,ny:n.y};e.setPointerCapture?.(ev.pointerId)}window.addEventListener('pointermove',ev=>{if(!drag)return;drag.nx=Math.round(drag.x+ev.clientX-drag.sx);drag.ny=Math.round(drag.y+ev.clientY-drag.sy);drag.e.style.left=drag.nx+'px';drag.e.style.top=drag.ny+'px'});window.addEventListener('pointerup',async()=>{if(!drag)return;let d=drag;drag=null;w=await api('/api/workspace',{op:'set_node',page_id:active,id:d.id,patch:{x:d.nx,y:d.ny}});render()});async function undo(){w=await api('/api/workspace',{op:'undo'});render()}async function verifyNow(){let v=await api('/api/verify');alert(v.ok?'VERIFY PASS':'VERIFY FAIL '+JSON.stringify(v.errors))}api('/api/workspace').then(x=>{w=x;render()});</script></body></html>'''
class H(base.H):
 def do_GET(self):
  path=self.path.split('?',1)[0]
  if path=='/':
   b=HTML.encode();self.send_response(200);self.send_header('Content-Type','text/html; charset=utf-8');self.send_header('Content-Length',str(len(b)));self.end_headers();self.wfile.write(b);return
  if path=='/asset/masthead.svg':
   p=ROOT/'static/images/westside-watch-masthead-landscape.svg'
   if p.exists():
    b=p.read_bytes();self.send_response(200);self.send_header('Content-Type','image/svg+xml');self.send_header('Content-Length',str(len(b)));self.end_headers();self.wfile.write(b);return
  if path=='/api/health':return self.out(200,{'ok':True,'service':'dore-design','version':'1.0','workspace':'new-westside','visual_grammar':['editorial-gravity','5:8','huarong-reflow','crenellation','dore-trace']})
  return super().do_GET()
if __name__=='__main__':ThreadingHTTPServer(('127.0.0.1',int(os.environ.get('DORE_DESIGN_PORT','4310'))),H).serve_forever()
